   202→func TestBuildCondensedTranscript_SkipsSkillContentInjection(t *testing.T) {
   203→	skillContent := `Base directory for this skill: /Users/alex/.claude/plugins/cache/superpowers/4.1.1/skills/brainstorming
   204→
   205→# Brainstorming Ideas Into Designs
   206→
   207→## Overview
   208→
   209→This is verbose skill content that should not appear in summaries...`
   210→
   211→	lines := []transcript.Line{
   212→		{
   213→			Type: "user",
   214→			UUID: "user-1",
   215→			Message: mustMarshal(t, transcript.UserMessage{
   216→				Content: "Invoke the superpowers:brainstorming skill",
   217→			}),
   218→		},
   219→		{
   220→			Type: "assistant",
   221→			UUID: "assistant-1",
   222→			Message: mustMarshal(t, transcript.AssistantMessage{
   223→				Content: []transcript.ContentBlock{
   224→					{Type: "tool_use", Name: "Skill", Input: mustMarshal(t, transcript.ToolInput{Skill: "superpowers:brainstorming"})},
   225→				},
   226→			}),
   227→		},
   228→		{
   229→			Type: "user",
   230→			UUID: "user-2",
   231→			Message: mustMarshal(t, transcript.UserMessage{
   232→				Content: skillContent, // This should be filtered out
   233→			}),
   234→		},
   235→		{
   236→			Type: "user",
   237→			UUID: "user-3",
   238→			Message: mustMarshal(t, transcript.UserMessage{
   239→				Content: "Now help me brainstorm a feature",
   240→			}),
   241→		},
   242→	}
   243→
   244→	entries := BuildCondensedTranscript(lines)
   245→
   246→	// Should have: user prompt, tool call, user prompt (NOT the skill content)
   247→	if len(entries) != 3 {
   248→		t.Fatalf("expected 3 entries (skill content filtered), got %d", len(entries))
   249→	}
   250→
   251→	// Verify the skill content was filtered
   252→	for _, entry := range entries {
   253→		if entry.Type == EntryTypeUser && strings.Contains(entry.Content, "Base directory for this skill") {
   254→			t.Error("skill content injection should have been filtered out")
   255→		}
   256→	}
   257→
   258→	// Verify the real user messages are present
   259→	if entries[0].Content != "Invoke the superpowers:brainstorming skill" {
   260→		t.Errorf("first user message wrong: %s", entries[0].Content)
   261→	}
   262→	if entries[2].Content != "Now help me brainstorm a feature" {
   263→		t.Errorf("last user message wrong: %s", entries[2].Content)
   264→	}
   265→}
