   497→func TestGenerateFromTranscript(t *testing.T) {
   498→	// Test with mock generator
   499→	mockGenerator := &ClaudeGenerator{
   500→		CommandRunner: func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
   501→			response := `{"result":"{\"intent\":\"Test intent\",\"outcome\":\"Test outcome\",\"learnings\":{\"repo\":[],\"code\":[],\"workflow\":[]},\"friction\":[],\"open_items\":[]}"}`
   502→			return exec.CommandContext(ctx, "sh", "-c", "printf '%s' '"+response+"'")
   503→		},
   504→	}
   505→
   506→	transcript := []byte(`{"type":"user","message":{"content":"Hello"}}
   507→{"type":"assistant","message":{"content":[{"type":"text","text":"Hi there"}]}}`)
   508→
   509→	summary, err := GenerateFromTranscript(context.Background(), transcript, []string{"file.go"}, mockGenerator)
   510→	if err != nil {
