    10→func TestClaudeGenerator_CommandNotFound(t *testing.T) {
    11→	gen := &ClaudeGenerator{
    12→		CommandRunner: func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
    13→			// Return a command that doesn't exist
    14→			return exec.CommandContext(ctx, "nonexistent-command-that-should-not-exist-12345")
    15→		},
    16→	}
    17→
    18→	input := Input{
    19→		Transcript: []Entry{
    20→			{Type: EntryTypeUser, Content: "Hello"},
    21→		},
    22→	}
    23→
    24→	_, err := gen.Generate(context.Background(), input)
    25→	if err == nil {
    26→		t.Fatal("expected error when command not found")
    27→	}
    28→
    29→	// The error message should indicate the command failed
    30→	if !strings.Contains(err.Error(), "not found") && !strings.Contains(err.Error(), "executable file not found") {
    31→		t.Errorf("expected 'not found' error, got: %v", err)
    32→	}
    33→}
