   483→// isSummariseEnabled checks if auto-summarise is enabled in settings.
   484→// Reads the settings file directly to avoid import cycles with the cli package.
   485→// Checks settings.local.json first, then settings.json.
   486→func isSummariseEnabled() bool {
   487→	// Try local settings first (user preference, not committed)
   488→	localSettingsPath, err := paths.AbsPath(".entire/settings.local.json")
   489→	if err != nil {
   490→		localSettingsPath = ".entire/settings.local.json"
   491→	}
   492→	if enabled, found := readSummariseEnabledFromFile(localSettingsPath); found {
   493→		return enabled
   494→	}
   495→
   496→	// Fall back to shared settings
   497→	sharedSettingsPath, err := paths.AbsPath(".entire/settings.json")
   498→	if err != nil {
   499→		sharedSettingsPath = ".entire/settings.json"
   500→	}
   501→	if enabled, found := readSummariseEnabledFromFile(sharedSettingsPath); found {
   502→		return enabled
   503→	}
   504→
   505→	// Default: summarise is disabled
   506→	return false
   507→}
